def sp_union_terms(items):
    if not items:
        return None
    value=items[len(items)-1]
    i=len(items)-2
    while i>=0:
        value=['participant_union',items[i],value]
        i-=1
    return value

def sp_action_positions(text):
    return_pos=-1
    destroy_pos=-1
    m=re.search(r'\breturn(?:ed|ing)?\b',text,re.I)
    if m is not None:
        return_pos=m.start()
    m=re.search(r'\bdeliver(?:ed|ing)?\b',text,re.I)
    if m is not None and sp_any(text,['deliver to','deliver all copies','deliver all such copies','deliver all copies of']):
        if return_pos<0 or m.start()<return_pos:
            return_pos=m.start()
    for pattern in (r'\bdestroy(?:ed|ing)?\b',r'\bdelete(?:d|ing)?\b',r'\berase(?:d|ing)?\b'):
        m=re.search(pattern,text,re.I)
        if m is not None and (destroy_pos<0 or m.start()<destroy_pos):
            destroy_pos=m.start()
    if 'not been destroyed or returned' in text:
        return_pos=-1
        destroy_pos=text.find('erase')
    return [return_pos,destroy_pos]

def sp_trigger(raw,context,kind):
    text=sp_low(raw)
    whole=sp_low(context)
    if 'returned to the disclosing party upon request or destroyed within ten' in text and 'project' in text:
        if kind=='return':
            return 'request'
        return 'project_end'
    if sp_any(text,['expiration or termination ofthis agreement','expiration or termination of this agreement']) and sp_any(text,['request of auditee','request by auditee']):
        return 'agreement_end_or_request'
    agreement=sp_any(whole,['termination of this agreement','expiration of this agreement','expiration or other termination of this agreement','termination of this confidentiality agreement','termination or expiration of this agreement','termination or expiration of the agreement'])
    project=sp_any(whole,['termination of the project','expiration of the project','expiration or other termination of the project'])
    relationship=sp_any(whole,['termination of the business relationship','termination/expiration of the business relation','termination of the working relationship'])
    nonformation=sp_any(whole,['business relationship is not entered','relationship is not entered','fail to enter into a business relationship'])
    abandonment=sp_any(whole,['determines not to proceed with the transaction','determine not to proceed with the transaction','decision not to proceed with the transaction'])
    service=sp_any(whole,['termination of service','service terminates'])
    request=sp_any(whole,['upon request','if requested','upon demand','written demand','written request','receipt of demand','so requests','at the request','request by','request of','request from'])
    affiliate='ceasing to be an affiliate' in whole
    if abandonment and request:
        return 'transaction_abandonment_or_request'
    if agreement and request:
        return 'agreement_end_or_request'
    if project and request:
        return 'project_end_or_request'
    if nonformation and request:
        return 'relationship_nonformation_or_request'
    if relationship and request:
        return 'relationship_end_or_request'
    if affiliate and request:
        return 'request_and_affiliate_exit'
    if abandonment:
        return 'transaction_abandonment'
    if agreement:
        return 'agreement_end'
    if project:
        return 'project_end'
    if relationship:
        return 'relationship_end'
    if nonformation:
        return 'relationship_nonformation'
    if service:
        return 'service_end'
    if request:
        return 'request'
    return 'unresolved_trigger'

def sp_disclosure(spans,out,unresolved):
    i=0
    while i<len(spans):
        uid=spans[i].get('id')
        raw=spans[i].get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        text=sp_low(raw)
        collective=sp_any(text,['collectively “representatives”','collectively "representatives"','collectively, “representatives”','collectively, "representatives"'])
        if collective:
            owner=['party']
            members=[]
            if 'employee' in text:
                members.append(['employees_of',owner])
            if 'director' in text:
                members.append(['directors_of',owner])
            if 'officer' in text:
                members.append(['officers_of',owner])
            if sp_any(text,['attorney','legal adviser','legal advisor','legal counsel']):
                members.append(['legal_advisors_of',owner])
            if sp_any(text,['financial adviser','financial advisor']):
                members.append(['financial_advisors_of',owner])
            if sp_any(text,['professional adviser','professional advisor']):
                members.append(['professional_advisors_of',owner])
            if 'accountant' in text:
                members.append(['accountants_of',owner])
            if 'consultant' in text:
                members.append(['consultants_of',owner])
            if 'contractor' in text:
                members.append(['independent_contractors_of',owner])
            if 'agent' in text:
                members.append(['agents_of',owner])
            if sp_any(text,['lender','financing source','finance provider']):
                members.append(['lenders_of',owner])
            members=sp_unique(members)
            if members:
                sp_add(out,['define_representative',owner,sp_union_terms(members)],[uid])
        context=sp_context(spans,i,2,1)
        ctext=sp_low(context)
        scope='unit:'+str(uid)
        permission=sp_any(ctext,['may disclose','may be disclosed','will disclose','restrict disclosure','restrict access','except in confidence','except its employees','except its employees,','only to disclose','disclosed only to','only share confidential information','only share information','reveal the information only to','reveal confidential information only to','may reveal','may be shared among','may share','may divulge'])
        internal_exception=('within its own organization' in text and sp_any(text,['except on a "need-to-know" basis','except on a “need-to-know” basis','except on a need-to-know basis']))
        if internal_exception:
            permission=True
        elliptical='obligations of the parties' in text and 'need to know' in text and not permission
        if elliptical:
            roles=[]
            if sp_any(text,['employee','staff','personnel']):
                roles.append('employee')
            if 'agent' in text:
                roles.append('agent')
            if 'representative' in text:
                roles.append('representative')
            for role in sp_unique(roles):
                sp_add(out,['acq_disclosure_v3',scope,'elliptical_recipient_permission_residual','receiving_party',role,'receiving_party','required','not_stated','required','source_stated_ellipsis',raw],[uid])
            if sp_any(text,['affiliate','any other individual','any other entity']):
                sp_add(out,['acq_disclosure_v3',scope,'elliptical_recipient_permission_residual','receiving_party','source_bounded_recipient','source_bounded','required','not_stated','required','source_stated_ellipsis',raw],[uid])
        need='required' if sp_any(ctext,['need to know','need-to-know','bona fide need']) else 'not_stated'
        extent='required' if sp_any(ctext,['extent necessary','extent absolutely necessary','strictly necessary','strictly necessary for','reasonably necessary','disclosure is necessary','involved in the performance']) else 'not_stated'
        confidentiality='written_required' if sp_any(ctext,['bound in writing','written agreement','written confidentiality agreement','agree in writing to act in accordance','mandatory non-disclosure agreement']) else 'required' if sp_any(ctext,['subject to the provisions','advise such employees','duty of confidentiality','bound by obligations','terms no less stringent','treat the confidential information','informed by us of the confidential nature','maintain all nonpublic information']) else 'not_stated'
        effect='class_permission' if ('except' in ctext or internal_exception) else 'operative_permission'
        actor='Auditor' if 'auditor shall' in text else 'Visitor' if 'visitor' in text else 'receiving_party'
        if permission:
            coordinated=sp_any(text,['employees or contractors','employees and contractors','employees and/or contractors','employee or contractor','employees and agents','employees or agents','employees and/or agents'])
            shared_employees=sp_any(text,['shared among','share with','reveal the information to']) and 'employee' in text
            direct_employee=sp_any(text,["recipient’s employees","recipient's employees",'its employees','members of its staff','employees, officers','employees and/or consultants','except its employees','only to such employees','only to employees','employees, advisors, and agents','employees, advisers, and agents']) or coordinated or shared_employees
            controlled_employee=sp_any(text,['employees of companies directly or indirectly owned or controlled','employees, officials, representatives and agents of any legal entity that it controls','under common control'])
            if direct_employee:
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'employee','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if internal_exception:
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'internal_personnel','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if controlled_employee:
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'employee','controlled_entity',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if 'consultant' in text:
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'consultant','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if 'contractor' in text:
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'contractor','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if 'agent' in text:
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'agent','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if sp_any(text,['professional adviser','professional advisor','advisors','advisers','legal advisor','legal adviser','financial advisor','financial adviser','attorney','accountant']):
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'professional_adviser','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
            if 'representative' in text and not sp_any(text,['employees','consultants','contractors','agents','advisers','advisors','attorneys','accountants']):
                sp_add(out,['acq_disclosure_v3',scope,effect,actor,'representative','receiving_party',need,extent,confidentiality,'source_stated_exception',raw],[uid])
        prohibited=sp_any(text,['shall not disclose','not disclose','not to disclose','will not without','not without']) and sp_any(text,['others','other person','other organization','third party','third parties','anyone'])
        if prohibited and not permission:
            authorization=sp_any(text,['consent','written approval','written authorization'])
            cross_reference=sp_any(text,['unless this agreement expressly permits','except as this agreement expressly permits','unless expressly permitted by this agreement'])
            exception='authorization_and_cross_reference' if authorization and cross_reference else 'authorization' if authorization else 'cross_reference' if cross_reference else 'source_stated_exception'
            sp_add(out,['acq_disclosure_v3',scope,'bounded_prohibition',actor,'source_outsiders','source_bounded','not_stated','not_stated','not_stated',exception,raw],[uid])
            if sp_any(text,['anyone','third party','third parties']):
                sp_add(out,['acq_disclosure_v3',scope,'bounded_prohibition',actor,'third_parties','source_bounded','not_stated','not_stated','not_stated',exception,raw],[uid])
        i+=1
